16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(OwnerMapper.initials(owner))")
23	    @Mapping(target = "membershipNumber", ignore = true)
24	    @Mapping(target = "customerCode", ignore = true)
25	    @Mapping(target = "membershipTier", ignore = true)
26	    OwnerDto toOwnerDto(Owner owner);
27	
28	    /** First letters of first and last name, upper-cased and dot-separated with a trailing dot, e.g. "J.S.". */
29	    static String initials(Owner owner) {
30	        return (owner.getFirstName().substring(0, 1) + "." + owner.getLastName().substring(0, 1) + ".")
31	                .toUpperCase();
32	    }
33	
34	    /**
35	     * The sequential membership number for the owner: one more than the number of owners that existed
36	     * before this one. Computed as the count of owners whose id is not greater than this owner's id.
37	     * Because a newly created owner always has the largest id, this equals the total owner count at
38	     * registration and stays stable when read back later.
39	     */
40	    static Integer membershipNumber(Owner owner, Collection<Owner> allOwners) {
41	        Integer id = owner.getId();
42	        if (id == null) {
43	            return null;
44	        }
45	        return (int) allOwners.stream()
46	                .filter(o -> o.getId() != null && o.getId() <= id)
47	                .count();
48	    }
49	
50	    /**
51	     * The per-city customer code for the owner, formatted {@code "<UPPERCASE_CITY>-<NNNN>"} where NNNN
52	     * is one more than the number of owners already in that city, zero-padded to four digits (e.g.
53	     * "LONDON-0007"). Computed as the count of owners in the same city (case-insensitive) whose id is
54	     * not greater than this owner's id. Because a newly created owner always has the largest id, this
55	     * equals the number already in that city plus one at registration and stays stable when read back
56	     * later.
57	     */
58	    static String customerCode(Owner owner, Collection<Owner> allOwners) {
59	        Integer id = owner.getId();
60	        String city = owner.getCity();
61	        if (id == null || city == null) {
62	            return null;
63	        }
64	        long sequence = allOwners.stream()
65	                .filter(o -> o.getId() != null && o.getId() <= id && city.equalsIgnoreCase(o.getCity()))
66	                .count();
67	        return String.format("%s-%04d", city.toUpperCase(), sequence);
68	    }
69	
70	    /**
71	     * The membership tier assigned to the owner at registration: {@code "FOUNDING"} for the first 100
72	     * owners ever created and {@code "STANDARD"} for all later owners. Derived from the sequential
73	     * {@link #membershipNumber(Owner, Collection) membership number}, so it is stable when read back later.
74	     */
75	    static String membershipTier(Owner owner, Collection<Owner> allOwners) {
76	        Integer number = membershipNumber(owner, allOwners);
77	        if (number == null) {
78	            return null;
79	        }
80	        return number <= 100 ? "FOUNDING" : "STANDARD";
